      const faqList = createElement("section", "faq-list");

      hero.append(eyebrow, title, intro);
      faqItems.forEach((item, index) => {
        faqList.appendChild(FAQItem({ ...item, index }));
      });

      shell.append(hero, faqList);
      return shell;
    }

    function App() {
      return FAQPage();
    }

    document.getElementById("app").appendChild(App());
  </script>
