      --surface-strong: #ffffff;
      --text: #132238;
      --muted: #5e7188;
      --border: rgba(19, 34, 56, 0.1);
      --shadow: 0 24px 60px rgba(36, 56, 99, 0.14);
      --accent: #4f46e5;
      --accent-soft: rgba(79, 70, 229, 0.12);
      --radius-xl: 28px;
      --radius-lg: 20px;
      --radius-md: 16px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(99, 102, 241, 0.16), transparent 32%),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.16), transparent 28%),
        var(--bg);
      color: var(--text);
    }

    .page-shell {
      width: min(960px, calc(100% - 32px));
      margin: 48px auto;
      padding: 40px;
      border: 1px solid var(--border);
      border-radius: var(--radius-xl);
      background: var(--surface);
      backdrop-filter: blur(16px);
      box-shadow: var(--shadow);
    }

    .hero {
      display: grid;
      gap: 18px;
      margin-bottom: 32px;
    }

    .eyebrow {
      width: fit-content;
      padding: 8px 14px;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent);
      font-size: 0.82rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.3rem, 4vw, 4rem);
      line-height: 1.02;
      letter-spacing: -0.04em;
    }

    .hero p {
      margin: 0;
      max-width: 680px;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.7;
    }

    .faq-list {
      display: grid;
      gap: 16px;
    }

    .example {
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--surface-strong);
      box-shadow: 0 12px 30px rgba(20, 30, 60, 0.06);
      overflow: hidden;
      transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
    }

    .example:hover {
      transform: translateY(-2px);
      box-shadow: 0 18px 36px rgba(20, 30, 60, 0.08);
      border-color: rgba(79, 70, 229, 0.18);
    }

    .question-button {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      padding: 22px 24px;
      border: 0;
      background: transparent;
      color: inherit;
      text-align: left;
      font: inherit;
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
    }

    .question-button:focus-visible {
      outline: 3px solid rgba(79, 70, 229, 0.28);
      outline-offset: -3px;
    }

    .question-label {
      line-height: 1.5;
    }

    .chevron {
      flex: 0 0 auto;
      width: 40px;
      height: 40px;
      display: grid;
      place-items: center;
      border-radius: 50%;
      background: var(--accent-soft);
      color: var(--accent);
      font-size: 1.2rem;
      transition: transform 180ms ease, background-color 180ms ease;
    }

    .question-button[aria-expanded="true"] .chevron {
      transform: rotate(45deg);
      background: rgba(79, 70, 229, 0.18);
    }

    .details {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 220ms ease;
    }

    .details.is-open {
      grid-template-rows: 1fr;
    }

    .details-inner {
      min-height: 0;
      overflow: hidden;
    }

    .answer {
      padding: 0 24px 22px;
      color: var(--muted);
      line-height: 1.75;
      font-size: 0.98rem;
      border-top: 1px solid rgba(19, 34, 56, 0.08);
    }

    .answer p {
      margin: 16px 0 0;
    }

    @media (max-width: 640px) {
      .page-shell {
        width: min(100% - 20px, 960px);
        margin: 20px auto;
        padding: 24px;
      }

      .question-button {
        padding: 18px 18px;
      }

      .answer {
        padding: 0 18px 18px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const faqItems = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel safe, comfortable, and content, but they may also purr to self-soothe when stressed or recovering. The sound is created by rapid muscle movements around the larynx, producing the familiar calming vibration."
      },
      {
        question: "How much sleep does a cat need?",
        answer: "Most adult cats sleep around 12 to 16 hours each day, with kittens and senior cats often resting even more. Their bursts of energy are balanced by long recovery periods, which is why naps are such a major part of cat life."
      },
      {
        question: "Do indoor cats need exercise?",
        answer: "Yes. Indoor cats benefit from daily play, climbing spaces, scratching posts, and toys that encourage chasing or problem-solving. Regular activity helps maintain a healthy weight and gives them an outlet for natural hunting behavior."
      },
      {
        question: "Why do cats knead with their paws?",
        answer: "Kneading starts in kittenhood during nursing and often carries into adulthood as a comfort behavior. Cats may knead when they are relaxed, claiming a soft spot, or showing affection toward a person or place they trust."
      },
      {
        question: "What should cats eat?",
        answer: "Cats are obligate carnivores, so they need a diet rich in animal-based protein and essential nutrients such as taurine. A complete, balanced cat food matched to their age and health needs is usually the best everyday choice."
      }
    ];

    function createElement(tag, className, text) {
      const element = document.createElement(tag);
      if (className) {
        element.className = className;
      }
      if (typeof text === "string") {
        element.textContent = text;
      }
      return element;
    }

    function FAQItem(props) {
      const { question, answer, index } = props;
      const section = createElement("div", "example");
      const button = createElement("button", "question-button");
      const label = createElement("span", "question-label", question);
      const chevron = createElement("span", "chevron", "+");
      const details = createElement("div", "details");
      const detailsInner = createElement("div", "details-inner");
      const answerWrap = createElement("div", "answer");
      const answerText = createElement("p", "", answer);
      const contentId = "faq-answer-" + index;

      button.type = "button";
      button.setAttribute("aria-expanded", "false");
      button.setAttribute("aria-controls", contentId);

      details.id = contentId;
      details.hidden = true;

      button.append(label, chevron);
      answerWrap.appendChild(answerText);
      detailsInner.appendChild(answerWrap);
      details.appendChild(detailsInner);
      section.append(button, details);

      button.addEventListener("click", () => {
        const isOpen = button.getAttribute("aria-expanded") === "true";
        button.setAttribute("aria-expanded", String(!isOpen));
        details.hidden = isOpen;
        details.classList.toggle("is-open", !isOpen);
      });

      return section;
    }

    function FAQPage() {
      const shell = createElement("main", "page-shell");
      const hero = createElement("section", "hero");
      const eyebrow = createElement("div", "eyebrow", "Cat Care FAQ");
      const title = createElement("h1", "", "Answers for curious cat people.");
      const intro = createElement(
        "p",
        "",
        "Browse a polished FAQ experience with quick guidance on common cat behaviors, care routines, and everyday questions. Every answer stays tucked away until you open it."
      );
      const faqList = createElement("section", "faq-list");

      hero.append(eyebrow, title, intro);
      faqItems.forEach((item, index) => {
        faqList.appendChild(FAQItem({ ...item, index }));
      });

      shell.append(hero, faqList);
      return shell;
    }

    function App() {
      return FAQPage();
    }

    document.getElementById("app").appendChild(App());
  </script>
</body>
</html>
