 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Cat FAQ</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --surface: rgba(255, 255, 255, 0.88);
       --surface-strong: #ffffff;
       --text: #132238;
       --muted: #5e7188;
       --border: rgba(19, 34, 56, 0.1);
       --shadow: 0 24px 60px rgba(36, 56, 99, 0.14);
       --accent: #4f46e5;
       --accent-soft: rgba(79, 70, 229, 0.12);
       --radius-xl: 28px;
       --radius-lg: 20px;
       --radius-md: 16px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top left, rgba(99, 102, 241, 0.16), transparent 32%),
         radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.16), transparent 28%),
         var(--bg);
       color: var(--text);
     }

     .page-shell {
       width: min(960px, calc(100% - 32px));
       margin: 48px auto;
       padding: 40px;
       border: 1px solid var(--border);
       border-radius: var(--radius-xl);
       background: var(--surface);
       backdrop-filter: blur(16px);
       box-shadow: var(--shadow);
     }

     .hero {
       display: grid;
       gap: 18px;
       margin-bottom: 32px;
     }

     .eyebrow {
       width: fit-content;
       padding: 8px 14px;
       border-radius: 999px;
       background: var(--accent-soft);
       color: var(--accent);
       font-size: 0.82rem;
       font-weight: 700;
       letter-spacing: 0.04em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(2.3rem, 4vw, 4rem);
       line-height: 1.02;
       letter-spacing: -0.04em;
     }

     .hero p {
       margin: 0;
       max-width: 680px;
       color: var(--muted);
       font-size: 1.05rem;
       line-height: 1.7;
     }

     .faq-list {
       display: grid;
       gap: 16px;
     }

     .example {
       border: 1px solid var(--border);
       border-radius: var(--radius-lg);
       background: var(--surface-strong);
       box-shadow: 0 12px 30px rgba(20, 30, 60, 0.06);
       overflow: hidden;
       transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
     }

     .example:hover {
       transform: translateY(-2px);
       box-shadow: 0 18px 36px rgba(20, 30, 60, 0.08);
       border-color: rgba(79, 70, 229, 0.18);
     }

     .question-button {
       width: 100%;
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 20px;
       padding: 22px 24px;
       border: 0;
       background: transparent;
       color: inherit;
       text-align: left;
       font: inherit;
       font-size: 1rem;
       font-weight: 700;
       cursor: pointer;
     }

     .question-button:focus-visible {
       outline: 3px solid rgba(79, 70, 229, 0.28);
       outline-offset: -3px;
     }

     .question-label {
       line-height: 1.5;
     }

     .chevron {
       flex: 0 0 auto;
       width: 40px;
       height: 40px;
       display: grid;
       place-items: center;
       border-radius: 50%;
       background: var(--accent-soft);
       color: var(--accent);
       font-size: 1.2rem;
       transition: transform 180ms ease, background-color 180ms ease;
     }

     .question-button[aria-expanded="true"] .chevron {
       transform: rotate(45deg);
       background: rgba(79, 70, 229, 0.18);
