       font-size: 0.98rem;
       border-top: 1px solid rgba(19, 34, 56, 0.08);
     }

     .answer p {
       margin: 16px 0 0;
     }

     @media (max-width: 640px) {
       .page-shell {
         width: min(100% - 20px, 960px);
         margin: 20px auto;
